# Writes lean/Fw/Measure/SimRetryData.lean from pieces.json. usage: python3 -I lean_data.py <pieces.json> <out.lean> [--check]
import json
import sys

src, out = sys.argv[1], sys.argv[2]
jobs = json.load(open(src))
lines = [
    '-- GENERATED by python3 -I results/sim-retry-needs/scripts/lean_data.py from results/sim-retry-needs/pieces.json: do not edit by hand',
    '/-! The gate decisions of the 98 green jobs of the wk-sim-hang sample: kind, seconds into the step, tries so far. -/',
    'namespace Fw.Measure.SimRetryData',
    '',
    'inductive Kind where',
    '  | scroll',
    '  | pass',
    '  | tab',
    'deriving DecidableEq, Repr',
    '',
    'structure Decision where',
    '  kind : Kind',
    '  atS : Nat',
    '  tries : Nat',
    'deriving Repr',
    '',
    'structure Job where',
    '  job : Nat',
    '  run : Nat',
    '  sessions : Nat',
    '  maxTries : Nat',
    '  decisions : List Decision',
    'deriving Repr',
    '',
]
names = []
for j in jobs:
    name = f"j{j['job']}"
    names.append(name)
    ds = ', '.join(f"⟨.{d['kind']}, {d['at']}, {d.get('tries', 1)}⟩" for d in j['decisions'])
    lines.append(f"def {name} : Job := ⟨{j['job']}, {j['run']}, {j['sessions']}, {j['maxTries']}, [{ds}]⟩")
    lines.append('')
lines.append('def jobs : List Job := [')
for i in range(0, len(names), 6):
    lines.append('  ' + ', '.join(names[i:i + 6]) + (',' if i + 6 < len(names) else ''))
lines.append(']')
lines.append('')
lines.append('end Fw.Measure.SimRetryData')
text = '\n'.join(lines) + '\n'
if '--check' in sys.argv[3:]:
    if open(out).read() != text:
        sys.exit(f'sim-retry data: {out} differs from the generated bytes')
    print(f'sim-retry data: {out} is up to date ({len(jobs)} jobs)')
else:
    open(out, 'w').write(text)
